import json, re

# Load existing catalog
text = open('src/models/floraDatabase.js', encoding='utf-8').read()
prefix = text.split('export const floraCatalog =')[0] + 'export const floraCatalog = [\n'
suffix = '\n];' + text.split('export const floraCatalog =')[1].split('\n];')[1]

array_str = text.split('export const floraCatalog =')[1].split('\nexport function getFloraById')[0].strip().rstrip(';')
existing_data = json.loads(array_str)

existing_names = set(d['commonName'].upper() for d in existing_data)
existing_ids = set(d['id'] for d in existing_data)

archetypes = ['ivory', 'golden_relic', 'cameo', 'hex_seal']

new_entries = []

def add_entry(name, domain, definition, lore, symbol, archetype_idx):
    c_name = name.strip().upper()
    if c_name in existing_names:
        return
    tile_id = 'tile_' + re.sub(r'[^a-z0-9]+', '_', c_name.lower()).strip('_')
    # ensure unique id
    base_id = tile_id
    counter = 1
    while tile_id in existing_ids:
        tile_id = f"{base_id}_{counter}"
        counter += 1
    
    arch = archetypes[archetype_idx % len(archetypes)]
    entry = {
        "id": tile_id,
        "commonName": c_name,
        "domain": domain,
        "definition": definition,
        "educationalLore": lore,
        "symbol": symbol,
        "archetype": arch,
        "class": f"archetype-{arch}",
        "letters": len(re.sub(r'[^A-Z]', '', c_name))
    }
    existing_names.add(c_name)
    existing_ids.add(tile_id)
    new_entries.append(entry)

